    bg=Counter(x for row in p for x in row).most_common(1)[0][0]
    cnt=Counter(x for row in p for x in row)
    H,W=len(p),len(p[0])
    objs=[]
    for col in {x for row in p for x in row}-{bg}:
        for comp in comps(p,col):
            objs.append((col,norm(comp)))
    groups={}
    for col,s in objs:
        groups.setdefault(norm(s),[]).append((col,s))
    # twin pair = two members with same shape (exact norm, not sym!) different colors; recolor one member to other's color
    for k,v in groups.items():
        if len(v)<2: continue
        (c1,s1),(c2,s2)=v[0],v[1]
        assert nrm(s1)==nrm(s2), 'norms must match'
        # which one is recolored? the one whose color count is larger? test both; choose by adjacency
        adj_c1=sum(abs(ra-rb)+abs(ca-cb)==1 for ra,ca in s1 for rb,cb in s2)
        if not adj_c1: continue
        tgt_col=c2
        src_obj=s1 if cnt[c1]>cnt[c2] else s2
        for r,c in src_obj:
            p[r][c]=tgt_col
    return p
