            objs.append((col,list(comp)))
    groups={}
    for col,cells in objs:
        groups.setdefault(nrm(cells),[]).append((col,cells))
    done=set()
    while True:
        for k,v in groups.items():
            if len(v)<2: continue
            for (a,ca),(b,cg) in itertools.combinations(v,2):
                if not any(abs(ra-rb)+abs(ca-cb)==1 for ra,ca in ca for rb,cb in cg): continue
                a2=(k,a); b2=(k,b)
                if a2 in done or b2 in done: continue
                tgt=cg[0] if cnt[cg[0]]<cnt[ca[0]] else ca[0]
                for r,c in ca if tgt==cg[0] else cg:
                    p[r][c]=tgt
                done.add(a2); done.add(b2)
            break
    return p
