t=open(os.path.normpath(os.environ['RLM_SESSION_DIR'])+'/../../sessions/'+os.path.basename(os.environ['RLM_SESSION_DIR'])+'.jsonl').read().replace('\\n','\n')
def grab(key,h,w):
    m=re.search(re.escape(key)+' \('+str(h)+'x'+str(w)+'):\n',t)
    if not m: return None
    return [[int(x) for x in r.split()] for r in t[m.end():].split('\n')[:h]]
